// Turns the After Dark packer's art.js (docs/after-dark-art/art.py writes it next to the atlases) into
// lib/afterdark-art.ts. node scripts/afterdark-art.mjs <path to art.js>
import { readFileSync, writeFileSync } from 'node:fs';
const src = readFileSync(process.argv[2] ?? 'public/art/after-dark/art.js', 'utf8');
const A = JSON.parse(src.slice(src.indexOf('{'), src.lastIndexOf('}') + 1));
const lines = [
  '// Generated by scripts/afterdark-art.mjs from the packer\'s art.js; do not edit by hand.',
  '// FRAMES: name -> [atlas, x, y, w, h, anchor x, anchor y], in atlas pixels; PX atlas pixels make one world unit.',
  '// Heroes are anchored by the head across and the feet down; props by their centre across and their base down.',
  `export const PX = ${A.PX};`,
  `export const ATLASES = ${JSON.stringify(A.atlases)} as const;`,
  `export const IMAGES: Record<string, [number, number]> = ${JSON.stringify(A.images)};`,
  'export const FRAMES: Record<string, [string, number, number, number, number, number, number]> = {',
  ...Object.keys(A.frames).sort().map((k) => `  '${k}': ${JSON.stringify(A.frames[k])},`),
  '};',
  '',
];
writeFileSync('lib/afterdark-art.ts', lines.join('\n'));
console.log(Object.keys(A.frames).length, 'frames,', A.atlases.length, 'atlases');
